<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { NAlert, NButton, NSelect, NSlider, NSwitch, NTag } from 'naive-ui';
import { Bot, Check, Hand, Monitor, Move, Palette, Sparkles } from 'lucide-vue-next';
import { EXPRESSIONS, EXPRESSION_NAMES, stillFrame } from '../../companion/expressions.ts';
import { robotDataUrl } from '../../companion/render.ts';
import { SKINS, SKIN_IDS, skinOf } from '../../companion/skins.ts';
import { invoke } from '../../bridge.ts';
import type { ControlStore } from '../control-types.ts';
import PetPreview from '../components/PetPreview.vue';
const props = defineProps<{ store: ControlStore }>();
const preview = ref<InstanceType<typeof PetPreview>>();
const busy = ref('');
const size = ref(props.store.settings.size);
let sizeTimer: ReturnType<typeof setTimeout> | null = null;
watch(() => props.store.settings.size, value => { if (!sizeTimer) size.value = value; });
function resize(value: number) {
  size.value = value;
  if (sizeTimer) clearTimeout(sizeTimer);
  sizeTimer = setTimeout(() => { sizeTimer = null; void act('size', () => props.store.updateAppearance({ size: value })); }, 180);
}
onBeforeUnmount(() => {
  if (sizeTimer) { clearTimeout(sizeTimer); void props.store.updateAppearance({ size: size.value }).catch(error => props.store.notify(error, 'error')); }
});
const skins = SKIN_IDS.map(id => ({ id, label: SKINS[id].label, image: robotDataUrl(stillFrame('happy'), 220, id) }));
const currentSkin = computed(() => skinOf(props.store.settings.companionSkin).id);
const expressions = EXPRESSION_NAMES.map(value => ({ value, label: EXPRESSIONS[value].label }));
const mood = computed(() => EXPRESSIONS[props.store.settings.expression as keyof typeof EXPRESSIONS]?.label ?? '平静');
async function act(key: string, action: () => Promise<void>) { busy.value = key; try { await action(); } catch (error) { props.store.notify(error, 'error'); } finally { busy.value = ''; } }
async function poke() { preview.value?.poke(); if (props.store.desktop) await invoke('poke'); }
</script>
<template>
  <section class="ui-page companion-page" data-testid="companion-page">

    <div class="companion-grid">
      <div class="surface companion-portrait"><div class="portrait-header"><span><Sparkles :size="15" />互动预览</span><NTag :bordered="false" size="small">{{ mood }}</NTag></div><div class="portrait-stage"><div class="portrait-orbit"></div><PetPreview ref="preview" :settings="store.settings" /><div class="portrait-ground"></div></div><h2>今天，也有小伴陪着你。</h2><p>移动鼠标，它会望向你。点一下，看看它的反应。</p><NButton secondary type="primary" @click="act('poke', poke)"><template #icon><Hand :size="16" /></template>戳戳小伴</NButton><div class="portrait-tip"><Move :size="14" />两种模式都可拖动小伴调整位置。</div></div>
      <div class="companion-options">
        <section class="surface"><div class="section-heading"><div><h2>盆栽植物</h2><p>花盆不变，换一株喜欢的植物陪着你</p></div><Palette :size="20" /></div><div class="skin-grid"><button v-for="skin in skins" :key="skin.id" type="button" :class="{ selected: currentSkin === skin.id }" :aria-pressed="currentSkin === skin.id" :disabled="!!busy" :data-testid="`skin-${skin.id}`" @click="act('skin', () => store.setCompanionSkin(skin.id))"><img :src="skin.image" alt="" width="110" height="96"><b>{{ skin.label }}</b><Check v-if="currentSkin === skin.id" :size="15" class="skin-check" /></button></div></section>
        <section class="surface"><div class="section-heading"><div><h2>陪伴方式</h2><p>显示状态与所在位置</p></div><Bot :size="20" /></div><div class="setting-row"><div><b>在桌面上显示小伴</b><p>关闭后壁纸继续运行，关怀提醒暂缓展示。</p></div><NSwitch data-testid="companion-enabled" :value="store.settings.companionEnabled" :loading="busy === 'visible'" :disabled="!!busy" @update:value="value => act('visible', () => store.setCompanion(value))" /></div><div class="setting-row"><div><b>小伴联动：让小伴回应特效和你的状态</b><p>只改变小伴的表情和动作，不弹窗、不发声。关闭后小伴只保留基础动作。</p></div><NSwitch data-testid="companion-links" :value="store.settings.companionLinks" :loading="busy === 'links'" :disabled="!!busy" @update:value="value => act('links', () => store.setCompanionLinks(value))" /></div><div class="placement-grid"><button :class="{ selected: store.settings.mode === 'floating' }" :disabled="!!busy" data-testid="mode-floating" @click="act('mode', () => store.setMode('floating'))"><span class="placement-preview floating-example"><Monitor :size="52" :stroke-width="1" /><img src="/xiaoban.svg" alt=""></span><b>悬浮桌宠</b><small>始终置顶，可自由拖动</small><Check v-if="store.settings.mode === 'floating'" :size="15" class="placement-check" /></button><button :class="{ selected: store.settings.mode === 'wallpaper' }" :disabled="!!busy" data-testid="mode-wallpaper" @click="act('mode', () => store.setMode('wallpaper'))"><span class="placement-preview wallpaper-example"><Monitor :size="52" :stroke-width="1" /><img src="/xiaoban.svg" alt=""></span><b>融入壁纸</b><small>不置顶，可自由拖动</small><Check v-if="store.settings.mode === 'wallpaper'" :size="15" class="placement-check" /></button></div></section>
        <section class="surface"><div class="section-heading"><div><h2>外观与心情</h2><p>设置会即时保存</p></div><Palette :size="20" /></div><div class="setting-row"><div><b>小伴的心情</b><p>选择一种喜欢的表情。</p></div><NSelect style="width:150px" :value="store.settings.expression" :options="expressions" :disabled="!!busy" @update:value="value => act('expression', () => store.updateAppearance({ expression: value }))" /></div><div class="size-field"><div><b>角色大小</b><span>{{ size }} px</span></div><NSlider :value="size" :min="160" :max="420" :step="10" :disabled="!!busy && busy !== 'size'" @update:value="resize" /><div><small>小巧</small><small>醒目</small></div></div></section>
        <div class="companion-links"><button @click="store.navigate('care')"><span>想让小伴提醒喝水、休息或下班？</span><b>设置关怀提醒 →</b></button><button @click="store.navigate('settings')"><span>动画暂停、帧率与开机启动</span><b>前往设置 →</b></button></div>
      </div>
    </div>
  </section>
</template>
