.companion-grid{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(360px,1.15fr);gap:24px}.companion-portrait{text-align:center;padding:24px;align-self:start;position:sticky;top:0}.portrait-header{display:flex;align-items:center;justify-content:space-between}.portrait-header>span{display:flex;gap:7px;align-items:center;font-size:12px;color:var(--ui-muted)}.portrait-stage{height:300px;display:grid;place-items:center;position:relative;margin:16px -10px;background:radial-gradient(ellipse at 50% 65%,color-mix(in srgb, var(--ui-primary-soft) 50%, transparent),transparent 67%)}.portrait-orbit{position:absolute;width:210px;height:210px;border:1px dashed var(--ui-border);border-radius:50%;top:24px}.portrait-ground{position:absolute;bottom:36px;left:20%;right:20%;height:12px;border-radius:50%;background:color-mix(in srgb, var(--ui-primary-soft) 21%, transparent);filter:blur(6px)}.portrait-stage :deep(.control-pet-preview){z-index:1}.companion-portrait h2{font-size:18px;margin:0 0 9px}.companion-portrait>p{color:var(--ui-muted);font-size:12px;line-height:1.8;margin-bottom:20px}.portrait-tip{display:flex;align-items:center;justify-content:center;gap:6px;border-top:1px solid var(--ui-line);margin-top:25px;padding-top:18px;font-size:12px;color:var(--ui-muted)}.companion-options{display:flex;flex-direction:column;gap:var(--ui-section-gap)}.companion-options>.surface{padding:24px}.placement-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}.placement-grid>button{position:relative;border:1px solid var(--ui-line);background:var(--ui-surface-alt);border-radius:11px;text-align:left;padding:14px;cursor:pointer;display:grid;gap:5px;color:var(--ui-text);transition:border-color .15s}.placement-grid>button.selected{border-color:var(--ui-primary);background:var(--ui-primary-soft);box-shadow:none}.placement-grid>button:hover{border-color:var(--ui-border)}.placement-grid small{font-size:12px;color:var(--ui-muted)}.placement-preview{height:66px;display:flex;align-items:center;position:relative;color:var(--ui-text-tertiary);margin-bottom:5px}.placement-preview img{position:absolute;width:27px;height:27px;left:37px;top:36px}.wallpaper-example img{left:14px;top:23px;width:22px;height:22px}.placement-check{position:absolute;right:12px;top:14px;color:var(--ui-primary)}.size-field{padding:20px 0;border-bottom:1px solid var(--ui-line)}.size-field>div{display:flex;justify-content:space-between;align-items:center}.size-field span{font-size:12px;color:var(--ui-primary);font-weight:600}.size-field :deep(.n-slider){margin:18px 0 10px}.size-field small{font-size:12px;color:var(--ui-muted)}.theme-choices{display:flex;gap:8px}.companion-links{display:grid;gap:10px}.companion-links button{border:0;background:transparent;display:flex;justify-content:space-between;gap:10px;font-size:12px;padding:6px 4px;cursor:pointer;text-align:left;color:var(--ui-muted)}.companion-links b{color:var(--ui-primary);white-space:nowrap}</style>
